# %% ../nbs/01_utils.ipynb 5
def calculate_log2fc(df, reference_column='MFDpir', count_threshold=20, pseudocount=1):
    """
    Filters a DataFrame, normalizes columns by sum, calculates log2 fold change
    relative to a reference column, and drops the reference column.

    Args:
        df (pd.DataFrame): Input DataFrame (rows=features, columns=samples).
        reference_column (str): Name of the reference sample column.
        count_threshold (int): Minimum count in reference column to keep a feature.
        pseudocount (float): Value added to normalized counts before log2FC.

    Returns:
        pd.DataFrame: DataFrame with log2 fold change values. None if reference
                      column is missing. Empty DataFrame if all rows are filtered out.
    """
    if reference_column not in df.columns:
        print(f"Error: Reference column '{reference_column}' not found in DataFrame.")
        return None

    # 1. Filter rows
    df_filtered = df[df[reference_column] > count_threshold].copy()
    if df_filtered.empty:
        print("DataFrame is empty after filtering.")
        return pd.DataFrame()

    # 2. Add pseudocount
    # The pseudocount is added here, before normalization.
    df_with_pseudocount = df_filtered + pseudocount

    # 3. Normalize each column by its sum
    # Normalization is now performed on the data that includes the pseudocount.
    # df.sum(axis=0) calculates sum for each column.
    # .div performs element-wise division, axis=1 aligns column_sums with columns.
    column_sums = df_with_pseudocount.sum(axis=0)
    
    # Handle cases where column_sums might be zero (e.g., if all values were -pseudocount after filtering, though unlikely with positive counts)
    # If a column sum is 0 after adding pseudocount, it implies an issue or very specific data.
    # Division by zero will result in NaN or inf.
    df_processed = df_with_pseudocount.div(column_sums, axis=1)

    # Check if reference column still exists (it should)
    if reference_column not in df_processed.columns:
        # This check is crucial as operations might alter columns if not handled carefully.
        print(f"Error: Reference column '{reference_column}' lost during processing.")
        return None
        
    reference_values = df_processed[reference_column]

    # 4. Calculate log2FC
    # .div performs element-wise division, axis=0 aligns reference_values (a Series) with rows of df_processed.
    log2fc_df = np.log2(df_processed.div(reference_values, axis=0))
    
    # Columns are already named correctly from df_processed.

    # 5. Drop the reference column's own log2FC (which will be ~zeros)
    if reference_column in log2fc_df.columns:
        log2fc_df = log2fc_df.drop(columns=[reference_column])
    else:
        print(f"Warning: Reference column '{reference_column}' not found in log2fc_df for dropping.")
        
    return log2fc_df

# %% ../nbs/01_utils.ipynb 8
def revcomp(seq:str):
    '''Computes the reverse complement of a sequence'''
    trns=str.maketrans("ATGCN","TACGN")
    return seq.upper().translate(trns)[::-1]

# %% ../nbs/01_utils.ipynb 10
bases=list("ATGC")
def allseqs(n,seqs=[""]):
    '''Recursive function that generates all possible sequences of length n
    seqs is a list of sequences to which we will add bases
    '''
    seqs=[s+b for s in seqs for b in bases]
    if len(seqs[0])<n:
        return allseqs(n,seqs)
    else:
        return seqs

# %% ../nbs/01_utils.ipynb 12
flatten = lambda l: [item for sublist in l for item in sublist]

# %% ../nbs/01_utils.ipynb 14
def get_all_sites(pattern):
    #generates a list of all sites that match the pattern
    return [s[:pattern[0]]+"N"*pattern[1]+s[pattern[0]:] for s in allseqs(pattern[0]+pattern[2])]


# %% ../nbs/01_utils.ipynb 16
def get_lib_seq_context(seqs,left,right):
    """
    Generates a list of sequences by combining a left and right sequence with each sequence in the input list.
    
    Args:
        seqs (list): List of sequences to be combined.
        left (str): Left sequence to prepend.
        right (str): Right sequence to append.

    Returns:
        list: List of combined sequences.
    """
    left=left.upper()
    right=right.upper()
    lib=[left+r+right for r in seqs]
    return lib

# %% ../nbs/01_utils.ipynb 18
def get_motif_presence_in_library(short_sequences_list, left_context, right_context, flexible_motifs_df):
    """
    Creates a DataFrame indicating the presence of flexible motifs in sequences (with context).

    Args:
        short_sequences_list (list): List of original short DNA sequences.
        left_context (str): Left context string to prepend.
        right_context (str): Right context string to append.
        flexible_motifs_df (pd.DataFrame): DataFrame of flexible motifs, must include
                                           a 'motif' column with motif strings (e.g., 'AACNNNNCTTT').

    Returns:
        pd.DataFrame: DataFrame with full sequences (with context) as index,
                      flexible motif strings as columns, and boolean values indicating presence.
    """
    if not isinstance(short_sequences_list, list):
        print("Error: short_sequences_list must be a list.")
        return pd.DataFrame()
    if not isinstance(flexible_motifs_df, pd.DataFrame) or 'motif' not in flexible_motifs_df.columns:
        print("Error: flexible_motifs_df is invalid or missing 'motif' column.")
        return pd.DataFrame()

    full_sequences_with_context = get_lib_seq_context(short_sequences_list, left_context, right_context)
    
    # Filter out None entries from full_sequences_with_context which may arise from non-string inputs to get_lib_seq_context
    # and keep track of original indices to align with short_sequences_list if needed for other purposes,
    # though for this function, we just use the valid full sequences.
    valid_full_sequences = [seq for seq in full_sequences_with_context if isinstance(seq, str)]
    if not valid_full_sequences:
        print("No valid full sequences to process after adding context.")
        return pd.DataFrame()

    unique_flexible_motifs = flexible_motifs_df['motif'].unique()
    
    presence_data = []

    for full_seq_str in valid_full_sequences:
        row_data = {'full_sequence': full_seq_str}
        for flex_motif_str in unique_flexible_motifs:
            if not isinstance(flex_motif_str, str) or not flex_motif_str:
                row_data[flex_motif_str] = False # Or handle as error/skip
                continue
            
            # Convert 'N' to '[ATGC]' for regex matching
            regex_pattern = flex_motif_str.replace('N', '[ATGC]')
            try:
                if re.search(regex_pattern, full_seq_str):
                    row_data[flex_motif_str] = True
                elif re.search(regex_pattern, revcomp(full_seq_str)):
                    row_data[flex_motif_str] = True
                else:
                    row_data[flex_motif_str] = False
            except re.error:
                # print(f"Warning: Regex error for motif '{flex_motif_str}' (pattern: '{regex_pattern}'). Marking as False.")
                row_data[flex_motif_str] = False
        presence_data.append(row_data)

    if not presence_data:
        return pd.DataFrame(index=valid_full_sequences, columns=unique_flexible_motifs)

    presence_df = pd.DataFrame(presence_data)
    if 'full_sequence' in presence_df.columns:
        presence_df = presence_df.set_index('full_sequence')
        
    return presence_df

